export function sourceLabeledGroupStageKeys(dashboard) {
  const keys = []
  for (const project of dashboard?.projects ?? []) for (const phase of project.phases ?? []) for (const scope of phase.scopes ?? []) for (const stage of scope.stages ?? []) {
    const meaningful = stage.gate?.available && (stage.gate.groups ?? []).some((group) => {
      const code = String(group.code ?? '').trim(); const name = String(group.name ?? '').trim()
      return Boolean(name && name !== code)
    })
    if (meaningful) keys.push(`${project.project?.id}:${stage.id}`)
  }
  return [...new Set(keys)]
}

export function assertSourceGroupOccurrences(name, expectedKeys, observedKeys) {
  const counts = (values) => values.reduce((map, key) => map.set(key, (map.get(key) ?? 0) + 1), new Map())
  const expected = counts(expectedKeys); const observed = counts(observedKeys); const missing = []; const unexpected = []
  for (const [key, count] of expected) for (let index = observed.get(key) ?? 0; index < count; index += 1) missing.push(key)
  for (const [key, count] of observed) for (let index = expected.get(key) ?? 0; index < count; index += 1) unexpected.push(key)
  if (missing.length || unexpected.length) throw new Error(`${name}: source-labeled Gate groups missing=${missing.join(',') || 'none'} unexpected=${unexpected.join(',') || 'none'}`)
}

async function focusContrast(page, selector) {
  const target = page.locator(selector); await target.focus()
  return target.evaluate((element) => {
    const style = getComputedStyle(element); const rgb = (value) => value.match(/[\d.]+/g)?.slice(0, 3).map(Number) ?? null
    const luminance = (channels) => channels.reduce((sum, channel, index) => { const value = channel / 255; const linear = value <= .04045 ? value / 12.92 : ((value + .055) / 1.055) ** 2.4; return sum + linear * [.2126, .7152, .0722][index] }, 0)
    const foreground = rgb(style.outlineColor); const background = rgb(style.backgroundColor); const contrast = foreground && background ? (Math.max(luminance(foreground), luminance(background)) + .05) / (Math.min(luminance(foreground), luminance(background)) + .05) : 0
    return { width: Number.parseFloat(style.outlineWidth), outline: style.outlineStyle, contrast }
  })
}

async function assertKeyboardContract(page, name) {
  const before = await page.locator('.oc-dashboard').evaluate((root) => `${root.dataset.currentStageId}|${root.querySelector('[data-current-signature]')?.textContent}|${root.querySelector('.oc-structure-band')?.dataset.structureSignature}`)
  const phaseOptions = page.locator('.oc-map-phase [role="option"]'); const phaseCount = await phaseOptions.count()
  await phaseOptions.first().focus()
  if (page.viewportSize().width >= 760) { await page.keyboard.press('End'); await page.waitForFunction(() => document.activeElement?.getAttribute('aria-selected') === 'true'); await page.keyboard.press('Home'); await page.waitForFunction(() => document.activeElement?.getAttribute('aria-selected') === 'true'); await page.keyboard.press('ArrowDown'); await page.waitForFunction(() => document.activeElement?.getAttribute('aria-selected') === 'true'); await page.keyboard.press('ArrowUp'); await page.waitForFunction(() => document.activeElement?.getAttribute('aria-selected') === 'true') }
  else await page.keyboard.press('ArrowLeft')
  const focus = await focusContrast(page, '.oc-map-phase [role="option"][aria-selected="true"]')
  if (phaseCount > 0) { await page.keyboard.press('ArrowRight'); try { await page.waitForFunction(() => document.activeElement?.closest('[data-column]')?.dataset.column === '2'); await page.keyboard.press('ArrowLeft'); await page.waitForFunction(() => document.activeElement?.closest('[data-column]')?.dataset.column === '1') } catch { throw new Error(`${name}: horizontal column focus movement failed`) } }
  const after = await page.locator('.oc-dashboard').evaluate((root) => `${root.dataset.currentStageId}|${root.querySelector('[data-current-signature]')?.textContent}|${root.querySelector('.oc-structure-band')?.dataset.structureSignature}`)
  if (after !== before) throw new Error(`${name}: hierarchy keyboard changed actual current truth`)
  if (focus.width < 3 || focus.outline === 'none' || focus.contrast < 3) throw new Error(`${name}: focus failed ${JSON.stringify(focus)}`)
  return focus.contrast
}

async function assertStage33PackageProjection(page) {
  const groups = await page.evaluate(() => [...document.querySelectorAll('.oc-groups article')].map((group) => ({ label: group.querySelector('strong')?.textContent?.trim(), code: group.querySelector('small')?.textContent?.replace('코드 ', '').trim(), total: Number(group.querySelector('b')?.textContent?.split('/')[1]) })))
  if (groups.length !== 9 || groups.reduce((sum, group) => sum + group.total, 0) !== 57 || stage33Expected.some(([code, label], index) => groups[index]?.code !== code || groups[index]?.label !== label)) throw new Error(`Stage33 Package labels failed: ${JSON.stringify(groups)}`)
}

